type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Get the length of the input array
    let a_len = a.len();
    
    // Check which dimension matches the array length
    if a_len == r {
        // Array is a column vector - broadcast across columns
        let mut matrix = Vec::with_capacity(r);
        
        for i in 0..r {
            let row = vec![a[i]; c];
            matrix.push(row);
        }
        
        matrix
    } else if a_len == c {
        // Array is a row vector - broadcast across rows
        let mut matrix = Vec::with_capacity(r);
        
        for _ in 0..r {
            matrix.push(a.clone());
        }
        
        matrix
    } else {
        // According to the problem statement, this shouldn't happen
        // as at least one dimension must match, but we handle it defensively
        panic!("Array length must match either R or C");
    }
}